import functools
import inspect
from typing import ForwardRef, get_type_hints
from fastapi.dependencies.utils import get_typed_signature

def wrap(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        return func(*args, **kwargs)
    return wrapper

def test_wrapped_method_forward_reference():
    class Outer:
        def method(self, a: "Outer") -> None:
            pass

    wrapped_method = wrap(Outer.method)
    # This should not raise NameError
    sig = get_typed_signature(wrapped_method)
    # Check if the annotation was resolved
    # The annotation for 'a' should be Outer
    param_a = sig.parameters['a']
    assert param_a.annotation is Outer

if __name__ == "__main__":
    import pytest
    pytest.main([__file__])

