import functools
import inspect
from typing import ForwardRef
from fastapi.dependencies.utils import get_typed_signature

def test_wrapped_method_forward_reference():
    # Simulate a wrapper from another module
    def wrap_sim(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            return func(*args, **kwargs)
        # Manually change globals to simulate another module
        wrapper.__globals__ = {} 
        return wrapper

    class Outer:
        def method(self, a: "Outer") -> None:
            pass

    wrapped_method = wrap_sim(Outer.method)

    # This should fail because wrapped_method.__globals__ is {}
    # but Outer.method.__globals__ contains Outer
    sig = get_typed_signature(wrapped_method)
    param_a = sig.parameters['a']
    assert param_a.annotation is Outer

if __name__ == "__main__":
    import pytest
    pytest.main([__file__])

